/**
 * @fileoverview Tests for yoda rule.
 * @author Raphael Pigulla
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------
const rule = require("../../../lib/rules/yoda"),
    { RuleTester } = require("../../../lib/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester();

ruleTester.run("yoda", rule, {
    valid: [

        // "never" mode
        { code: 'if (value === "red") {}', options: ["never"] },
        { code: "if (value === value) {}", options: ["never"] },
        { code: "if (value != 5) {}", options: ["never"] },
        { code: "if (5 & foo) {}", options: ["never"] },
        { code: "if (5 === 4) {}", options: ["never"] },
        {
            code: "if (value === `red`) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (`red` === `red`) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (`${foo}` === `red`) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: 'if (`${""}` === `red`) {}',
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: 'if (`${"red"}` === foo) {}',
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (b > `a` && b > `a`) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: 'if (`b` > `a` && "b" > "a") {}',
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },

        // "always" mode
        { code: 'if ("blue" === value) {}', options: ["always"] },
        { code: "if (value === value) {}", options: ["always"] },
        { code: "if (4 != value) {}", options: ["always"] },
        { code: "if (foo & 4) {}", options: ["always"] },
        { code: "if (5 === 4) {}", options: ["always"] },
        {
            code: "if (`red` === value) {}",
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (`red` === `red`) {}",
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (`red` === `${foo}`) {}",
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: 'if (`red` === `${""}`) {}',
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: 'if (foo === `${"red"}`) {}',
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (`a` > b && `a` > b) {}",
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: 'if (`b` > `a` && "b" > "a") {}',
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },

        // Range exception
        {
            code: 'if ("a" < x && x < MAX ) {}',
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (1 < x && x < MAX ) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if ('a' < x && x < MAX ) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (x < `x` || `x` <= x) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (0 < x && x <= 1) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (0 <= x && x < 1) {}",
            options: ["always", { exceptRange: true }]
        },
        {
            code: "if ('blue' < x.y && x.y < 'green') {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (0 < x[``] && x[``] < 100) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (0 < x[''] && x[``] < 100) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code:
                "if (a < 4 || (b[c[0]].d['e'] < 0 || 1 <= b[c[0]].d['e'])) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (0 <= x['y'] && x['y'] <= 100) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (a < 0 && (0 < b && b < 1)) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if ((0 < a && a < 1) && b < 0) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (-1 < x && x < 0) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (0 <= this.prop && this.prop <= 1) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (0 <= index && index < list.length) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (ZERO <= index && index < 100) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (value <= MIN || 10 < value) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (value <= 0 || MAX < value) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: 'if (0 <= a.b && a["b"] <= 100) {}',
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (0 <= a.b && a[`b`] <= 100) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (-1n < x && x <= 1n) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2020 }
        },
        {
            code: "if (-1n <= x && x < 1n) {}",
            options: ["always", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2020 }
        },
        {
            code: "if (x < `1` || `1` < x) {}",
            options: ["always", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2020 }
        },
        {
            code: "if (1 <= a['/(?<zero>0)/'] && a[/(?<zero>0)/] <= 100) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2018 }
        },
        {
            code: "if (x <= `bar` || `foo` < x) {}",
            options: ["always", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if ('a' < x && x < MAX ) {}",
            options: ["always", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if ('a' < x && x < MAX ) {}",
            options: ["always"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (MIN < x && x < 'a' ) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (MIN < x && x < 'a' ) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (`blue` < x.y && x.y < `green`) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (0 <= x[`y`] && x[`y`] <= 100) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: 'if (0 <= x[`y`] && x["y"] <= 100) {}',
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if ('a' <= x && x < 'b') {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (x < -1n || 1n <= x) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2020 }
        },
        {
            code: "if (x < -1n || 1n <= x) {}",
            options: ["always", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2020 }
        },
        {
            code: "if (1 < a && a <= 2) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (x < -1 || 1 < x) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (x <= 'bar' || 'foo' < x) {}",
            options: ["always", { exceptRange: true }]
        },
        {
            code: "if (x < 0 || 1 <= x) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if('a' <= x && x < MAX) {}",
            options: ["never", { exceptRange: true }]
        },
        {
            code: "if (0 <= obj?.a && obj?.a < 1) {}",
            options: ["never", { exceptRange: true }],
            parserOptions: { ecmaVersion: 2020 }
        },

        // onlyEquality
        {
            code: "if (0 < x && x <= 1) {}",
            options: ["never", { onlyEquality: true }]
        },
        {
            code: "if (x !== 'foo' && 'foo' !== x) {}",
            options: ["never", { onlyEquality: true }]
        },
        {
            code: "if (x < 2 && x !== -3) {}",
            options: ["always", { onlyEquality: true }]
        },
        {
            code: "if (x !== `foo` && `foo` !== x) {}",
            options: ["never", { onlyEquality: true }],
            parserOptions: { ecmaVersion: 2015 }
        },
        {
            code: "if (x < `2` && x !== `-3`) {}",
            options: ["always", { onlyEquality: true }],
            parserOptions: { ecmaVersion: 2015 }
        }
    ],
    invalid: [
        {
            code: "if (x <= 'foo' || 'bar' < x) {}",
            output: "if ('foo' >= x || 'bar' < x) {}",
            options: ["always", { exceptRange: true }],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "left", operator: "<=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: 'if ("red" == value) {}',
            output: 'if (value == "red") {}',
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "==" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (true === value) {}",
            output: "if (value === true) {}",
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "===" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (5 != value) {}",
            output: "if (value != 5) {}",
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "!=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (5n != value) {}",
            output: "if (value != 5n) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2020 },
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "!=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (null !== value) {}",
            output: "if (value !== null) {}",
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "!==" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: 'if ("red" <= value) {}',
            output: 'if (value >= "red") {}',
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "<=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (`red` <= value) {}",
            output: "if (value >= `red`) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 },
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "<=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (`red` <= `${foo}`) {}",
            output: "if (`${foo}` >= `red`) {}",
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 },
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "<=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: 'if (`red` <= `${"red"}`) {}',
            output: 'if (`${"red"}` >= `red`) {}',
            options: ["never"],
            parserOptions: { ecmaVersion: 2015 },
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "<=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (true >= value) {}",
            output: "if (value <= true) {}",
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: ">=" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "var foo = (5 < value) ? true : false",
            output: "var foo = (value > 5) ? true : false",
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "<" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "function foo() { return (null > value); }",
            output: "function foo() { return (value < null); }",
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: ">" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: "if (-1 < str.indexOf(substr)) {}",
            output: "if (str.indexOf(substr) > -1) {}",
            options: ["never"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "right", operator: "<" },
                    type: "BinaryExpression"
                }
            ]
        },
        {
            code: 'if (value == "red") {}',
            output: 'if ("red" == value) {}',
            options: ["always"],
            errors: [
                {
                    messageId: "expected",
                    data: { expectedSide: "left", operator: "==" },
                    type: "BinaryExpression"
                }
            ]
